import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec(torch::Tensor A, torch::Tensor B);
"""

matvec_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cstdint>

#include <cute/tensor.hpp>

using namespace cute;

// C[m] = sum_k A[m,k] * B[k]
// A: (M,K) row-major contiguous, B: (K,) contiguous, C: (M,)
// Split-K: the (very large) reduction dimension K is partitioned into
// slices of Kc elements; blockIdx.y selects the slice. Each block streams
// its slice with vectorized 16B loads through CUTE global-memory tensors,
// reduces with a warp/shared-memory tree, and atomically accumulates the
// partial dot product into C[m]. Kc is a multiple of 4 so every slice
// base stays 16-byte aligned on the vectorized path.
template <int BlockSize, int Unroll>
__global__ void matvec_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              int M, int K, int Kc)
{
  const int m     = blockIdx.x;
  const int slice = blockIdx.y;
  const int tid   = threadIdx.x;
  // Split-K: this block covers [kStart, kStart + kLen) of the reduction.
  const int kStart = slice * Kc;
  const int kLen   = min(K - kStart, Kc);
  const float* aRow = A + (int64_t)m * (int64_t)K + kStart;
  const float* bSl  = B + kStart;
  float acc[Unroll];
  #pragma unroll
  for (int u = 0; u < Unroll; ++u) acc[u] = 0.0f;
  // Kc % 4 == 0, so all slice bases remain 16B aligned when the global
  // base pointers are aligned and K % 4 == 0.
  const bool vecOk = ((K & 3) == 0) &&
                     ((reinterpret_cast<uintptr_t>(A) & 0xF) == 0) &&
                     ((reinterpret_cast<uintptr_t>(B) & 0xF) == 0);
  if (vecOk) {
    const int Kv = kLen >> 2;  // number of float4 elements in this slice
    // CUTE global tensors viewed as 16-byte vectors => fully coalesced
    // vectorized loads (thread i reads element i, i+BlockSize, ...).
    Tensor gAv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(aRow)),
                             make_shape(Kv), make_stride(Int<1>{}));
    Tensor gBv = make_tensor(make_gmem_ptr(reinterpret_cast<const float4*>(bSl)),
                             make_shape(Kv), make_stride(Int<1>{}));
    int i = tid;
    // Unrolled main loop: Unroll outstanding 16B load pairs in flight.
    for (; i + (Unroll - 1) * BlockSize < Kv; i += Unroll * BlockSize) {
      float4 a[Unroll], b[Unroll];
      #pragma unroll
      for (int u = 0; u < Unroll; ++u) {
        a[u] = gAv(i + u * BlockSize);
        b[u] = gBv(i + u * BlockSize);
      }
      #pragma unroll
      for (int u = 0; u < Unroll; ++u) {
        acc[u] = fmaf(a[u].x, b[u].x, acc[u]);
        acc[u] = fmaf(a[u].y, b[u].y, acc[u]);
        acc[u] = fmaf(a[u].z, b[u].z, acc[u]);
        acc[u] = fmaf(a[u].w, b[u].w, acc[u]);
      }
    }
    // Remaining whole vectors.
    for (; i < Kv; i += BlockSize) {
      float4 a = gAv(i);
      float4 b = gBv(i);
      acc[0] = fmaf(a.x, b.x, fmaf(a.y, b.y, fmaf(a.z, b.z, fmaf(a.w, b.w, acc[0]))));
    }
  } else {
    // Generic scalar fallback (still CUTE tensors, still coalesced).
    Tensor gA = make_tensor(make_gmem_ptr(aRow), make_shape(kLen), make_stride(Int<1>{}));
    Tensor gB = make_tensor(make_gmem_ptr(bSl),  make_shape(kLen), make_stride(Int<1>{}));
    for (int k = tid; k < kLen; k += BlockSize) {
      acc[0] = fmaf(gA(k), gB(k), acc[0]);
    }
  }
  // Combine per-thread accumulator chains.
  float sum = 0.0f;
  #pragma unroll
  for (int u = 0; u < Unroll; ++u) sum += acc[u];
  // Warp reduction.
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1)
    sum += __shfl_down_sync(0xffffffffu, sum, off);
  constexpr int NumWarps = BlockSize / 32;
  __shared__ float sPart[NumWarps];
  const int lane = tid & 31;
  const int wid  = tid >> 5;
  if (lane == 0) sPart[wid] = sum;
  __syncthreads();
  if (wid == 0) {
    float v = (lane < NumWarps) ? sPart[lane] : 0.0f;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1)
      v += __shfl_down_sync(0xffffffffu, v, off);
    // Combine this slice's partial dot product across split-K blocks.
    if (lane == 0) atomicAdd(&C[m], v);
  }
}

torch::Tensor matvec(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A must be (M,K), B must be (K,1)");
  TORCH_CHECK(B.size(1) == 1, "B must have shape (K,1)");
  TORCH_CHECK(A.size(1) == B.size(0), "inner dimensions must match");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  const int64_t M = A_c.size(0);
  const int64_t K = A_c.size(1);
  TORCH_CHECK(M > 0 && K > 0, "M and K must be positive");
  TORCH_CHECK(M < (int64_t)INT32_MAX && K < (int64_t)INT32_MAX,
              "M and K must fit in int32");

  // Split-K: partition the very large reduction dimension across several
  // blocks per row to expose more parallelism / memory-level parallelism.
  // Kc is rounded up to a multiple of 4 so every slice base stays 16-byte
  // aligned on the vectorized float4 path.
  constexpr int SplitK = 8;
  int64_t Kc = (K + SplitK - 1) / SplitK;
  Kc = (Kc + 3) & ~int64_t(3);
  const int64_t S = (K + Kc - 1) / Kc;
  // Zero-initialized: split-K partials are combined with atomicAdd.
  auto C = torch::zeros({M, 1}, A_c.options());
  constexpr int BlockSize = 256;
  constexpr int Unroll    = 4;
  dim3 grid((unsigned)M, (unsigned)S);
  dim3 block(BlockSize);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matvec_kernel<BlockSize, Unroll><<<grid, block, 0, stream>>>(
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>(),
      (int)M, (int)K, (int)Kc);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=matvec_cpp_decl,
    cuda_sources=matvec_cuda_src,
    functions=["matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A @ B) implemented with a single
    custom CUTE/CUDA split-K kernel: the very large K reduction dimension
    is partitioned across several thread blocks per output row, each
    streaming its K-slice with vectorized float4 loads through CUTE
    global tensors; partial dot products from the warp/shared-memory
    tree reduction are combined with atomicAdd.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        if A.dtype != torch.float32:
            A = A.float()
        if B.dtype != torch.float32:
            B = B.float()
        return self._ext.matvec(A, B)

